WITH p AS (SELECT %s::date d1,%s::date d2,coalesce(%s::text,'') ma_kh,coalesce(%s::text,'') ma_vt,%s::integer uid,%s::integer lim),s AS (SELECT p.*,u.user_id ok,coalesce(u.ds_branchs,'') bs,coalesce(u.is_super,0)=1 OR coalesce(u.ds_branchs,'')='' all_branch FROM p LEFT JOIN public.userinfo u ON u.user_id=p.uid) SELECT row_number() OVER(ORDER BY d.ma_kh,c.ma_vt,c.ngay_bd DESC) stt,d.ma_kh,c.ma_vt,v.ten_vt,c.ngay_bd,c.ngay_kt,c.ngay_kt_old,c.gia0,c.gia,c.ma_nt,c.ma_thue,c.thue_suat,c.sl_min,c.status,count(*) OVER() total FROM public.dmgiamua d JOIN public.dmgiamuact c ON c.ma_kh=d.ma_kh AND c.ngay_bd=d.ngay_bd LEFT JOIN public.dmvt v ON v.ma_vt=c.ma_vt CROSS JOIN s WHERE s.ok IS NOT NULL AND c.ngay_bd BETWEEN s.d1 AND s.d2 AND (s.ma_kh='' OR d.ma_kh=ANY(string_to_array(s.ma_kh,','))) AND (s.ma_vt='' OR c.ma_vt=ANY(string_to_array(s.ma_vt,','))) AND (s.all_branch OR coalesce(v.ds_ma_dvcs,'')='' OR EXISTS(SELECT 1 FROM unnest(string_to_array(s.bs,',')) x WHERE x=ANY(string_to_array(v.ds_ma_dvcs,',')))) ORDER BY d.ma_kh,c.ma_vt,c.ngay_bd DESC LIMIT (SELECT lim FROM p);
